import {Plus, Trash2} from 'lucide-react';
import {useState} from 'react';
import {get, useFieldArray, useFormContext} from 'react-hook-form';
import {ProductValues} from '@/lib/validation/productSchema';

const QUICK_SIZES = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];

/**
 * Sizes x colors table. Variant SKUs are generated by the backend; leaving a
 * saved row out turns it off (it stays for stock and order history).
 */
const VariantEditor = ({disabled}: {disabled?: boolean}) => {
  const {
    control,
    register,
    formState: {errors},
  } = useFormContext<ProductValues>();
  const {fields, append, remove} = useFieldArray({control, name: 'variants'});
  const [quickColor, setQuickColor] = useState('');
  const listError = get(errors, 'variants')?.message as string | undefined;

  const addSizes = () => {
    const color = quickColor.trim();
    if (!color) return;
    QUICK_SIZES.forEach((size) =>
      append({
        size,
        color,
        colorHex: '',
        mrp: '',
        sellingPrice: '',
        isActive: true,
      }),
    );
    setQuickColor('');
  };

  const cell = 'field-input px-2 py-1.5 text-body-sm';

  return (
    <div>
      <div className="overflow-x-auto">
        <table className="w-full min-w-[36rem] text-left">
          <thead>
            <tr className="text-label-caps uppercase text-outline">
              <th className="pb-2 pr-2 font-semibold">Size *</th>
              <th className="pb-2 pr-2 font-semibold">Color *</th>
              <th className="pb-2 pr-2 font-semibold">MRP</th>
              <th className="pb-2 pr-2 font-semibold">Price</th>
              <th className="pb-2 pr-2 font-semibold">Stock</th>
              <th className="pb-2 pr-2 font-semibold">On</th>
              <th className="pb-2" />
            </tr>
          </thead>
          <tbody>
            {fields.map((row, i) => {
              const err = (k: string) =>
                get(errors, `variants.${i}.${k}`)?.message as
                  | string
                  | undefined;
              const rowError =
                err('size') ??
                err('color') ??
                err('sellingPrice') ??
                err('mrp');
              return (
                <tr key={row.id} className="align-top">
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.size`)}
                      aria-label={`Variant ${i + 1} size`}
                      aria-invalid={!!err('size')}
                      placeholder="M"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.color`)}
                      aria-label={`Variant ${i + 1} color`}
                      aria-invalid={!!err('color')}
                      placeholder="Navy Blue"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.mrp`)}
                      inputMode="decimal"
                      aria-label={`Variant ${i + 1} MRP`}
                      aria-invalid={!!err('mrp')}
                      placeholder="Same"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.sellingPrice`)}
                      inputMode="decimal"
                      aria-label={`Variant ${i + 1} price`}
                      aria-invalid={!!err('sellingPrice')}
                      placeholder="Same"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2 pt-2 text-body-sm text-outline">
                    {row.available ?? '–'}
                  </td>
                  <td className="pb-2 pr-2 pt-2">
                    <input
                      type="checkbox"
                      {...register(`variants.${i}.isActive`)}
                      aria-label={`Variant ${i + 1} active`}
                      className="h-4 w-4 accent-burgundy"
                    />
                  </td>
                  <td className="pb-2">
                    <button
                      type="button"
                      onClick={() => remove(i)}
                      disabled={disabled || fields.length === 1}
                      aria-label={`Remove variant ${i + 1}`}
                      className="btn-icon h-8 w-8 hover:text-error disabled:opacity-30"
                    >
                      <Trash2 size={14} />
                    </button>
                    {rowError && (
                      <p role="alert" className="field-error whitespace-nowrap">
                        {rowError}
                      </p>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {listError && (
        <p role="alert" className="field-error">
          {listError}
        </p>
      )}
      {!disabled && (
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() =>
              append({
                size: '',
                color: '',
                colorHex: '',
                mrp: '',
                sellingPrice: '',
                isActive: true,
              })
            }
            className="btn-text"
          >
            <Plus size={12} /> Add variant
          </button>
          <span className="text-technical-data text-outline">
            or add XS–XXL for color
          </span>
          <input
            value={quickColor}
            onChange={(e) => setQuickColor(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                addSizes();
              }
            }}
            placeholder="e.g. Black"
            aria-label="Color for all sizes"
            className="field-input w-32 px-2 py-1 text-body-sm"
          />
          <button type="button" onClick={addSizes} className="btn-text">
            Add sizes
          </button>
        </div>
      )}
    </div>
  );
};

export default VariantEditor;
